interface AnalyticsTracker { fun log(event: String) }

class FirebaseTracker @Inject constructor(
  private val firebase: FirebaseAnalytics
) : AnalyticsTracker {
  override fun log(event: String) = firebase.logEvent(event, null)
}

@Module
@InstallIn(SingletonComponent::class)
abstract class AnalyticsModule {

  // ✅ @Binds — abstract, exactly one parameter, no body
  @Binds
  @Singleton
  abstract fun bindTracker(impl: FirebaseTracker): AnalyticsTracker

  companion object {
    // ✅ @Provides — a type we do not own, needs configuration
    @Provides
    @Singleton
    fun provideFirebase(@ApplicationContext ctx: Context): FirebaseAnalytics =
      FirebaseAnalytics.getInstance(ctx)
  }
}

