class OrderLoader @AssistedInject constructor(
  @Assisted private val orderId: String,   // runtime value
  private val repo: OrderRepository        // from the graph
) {
  suspend fun load(): Order = repo.load(orderId)

  @AssistedFactory
  interface Factory { fun create(orderId: String): OrderLoader }
}

@HiltViewModel
class OrderViewModel @Inject constructor(
  state: SavedStateHandle,                 // nav args land here
  loaderFactory: OrderLoader.Factory
) : ViewModel() {
  private val orderId: String = checkNotNull(state["orderId"])
  private val loader = loaderFactory.create(orderId)

  val ui = flow { emit(loader.load()) }
    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), null)
}

class ReportGenerator @Inject constructor(
  private val db: Lazy<AppDatabase>,             // opened on first get(), then cached
  private val sessions: Provider<Session>        // a fresh Session per call
) {
  fun run(): Report {
    val dao = db.get().reports()                 // DB opened only if run() is called
    return dao.build(sessions.get())
  }
}

// Breaking a cycle: TokenStore needs the Api to refresh, the Api needs the TokenStore
class TokenStore @Inject constructor(
  private val api: Provider<AuthApi>             // resolved at call time, not construction
) {
  suspend fun refresh() = api.get().refresh(current())
}

class AuthInterceptor @Inject constructor(
  private val tokens: TokenStore
) : Interceptor

@HiltWorker
class SyncWorker @AssistedInject constructor(
  @Assisted appContext: Context,
  @Assisted params: WorkerParameters,
  private val repo: FeedRepository
) : CoroutineWorker(appContext, params) {
  override suspend fun doWork(): Result {
    repo.sync()
    return Result.success()
  }
}

